import assert from'node:assert/strict';
/** Independently fixed original table geometry. No production model import. */
const values=[['8.0','5.0','3.0','1.5','1.5','5件'],['8.0','4.0','4.0','1.2','2.8','4件'],['8.0','4.0','4.0','1.6','2.4','4件']];
export function planningReviewedSalesAlt(c:readonly string[]){return`1日の業務活動の時間分析表。総業務時間${c[0]}時間の内訳は顧客訪問時間${c[1]}時間と社内業務時間${c[2]}時間。社内業務時間の内訳は訪問準備時間${c[3]}時間とその他業務時間${c[4]}時間。別枠の1日の顧客訪問件数は${c[5]}。`;}
const attr=(s:string,k:string)=>{const x=s.match(new RegExp(`(?:^|\\s)${k}="([^"]*)"`));assert(x,`${k}: ${s}`);return x[1];};
// Original question61, physical p25: the title is above the main table, separate from its six headings.
// Original PNG SHA256: 3fb3baafdb37edc4cf9ae60332c4d2ebb45cb08da60cdf7c494bbbc248021eab.
export function readPlanningSalesSvg(svg:string,v:number){assert(Number.isInteger(v)&&v>=0&&v<=2);assert.match(svg,/viewBox="0 0 900 400"/);
 const titles=[...svg.matchAll(/<text ([^>]*data-sales-source-title=[^>]+)>([^<]*)<\/text>/g)];assert.equal(titles.length,1);const title=titles[0];assert.equal(attr(title[1],'data-sales-source-title'),'true');assert.equal(Number(attr(title[1],'x')),690);assert.equal(Number(attr(title[1],'y')),22);assert.equal(attr(title[1],'text-anchor'),'end');assert.equal(title[2],'1日の業務活動の時間分析表');const boxes=[...svg.matchAll(/<rect ([^>]+)>/g)];assert.equal(boxes.length,2);const expectedBoxes=[['main','40','40','650','320'],['count','730','40','130','320']];assert.deepEqual(boxes.map(m=>['data-sales-box','x','y','width','height'].map(k=>attr(m[1],k))),expectedBoxes);
 const rules=[...svg.matchAll(/<line ([^>]+)>/g)];assert.equal(rules.length,8);assert.deepEqual(rules.map(m=>['data-sales-rule','x1','y1','x2','y2'].map(k=>Number(attr(m[1],k)))),[[0,170,90,690,90],[1,430,140,690,140],[2,40,310,690,310],[3,730,310,860,310],[4,170,90,170,360],[5,300,90,300,360],[6,430,140,430,360],[7,560,140,560,360]]);
 const headings=[...svg.matchAll(/<text ([^>]*data-sales-heading=[^>]+)>(.*?)<\/text>/g)];assert.equal(headings.length,6);const fixed=[['total',365,75,['総業務時間']],['visit',235,150,['顧客','訪問','時間']],['inside',495,125,['社内業務時間']],['preparation',495,180,['訪問','準備','時間']],['other',625,180,['その他','業務','時間']],['count',795,110,['1日の','顧客','訪問','件数']]]as const;
 headings.forEach((m,i)=>{const[k,x,y,lines]=fixed[i];assert.equal(attr(m[1],'data-sales-heading'),k);assert.equal(Number(attr(m[1],'x')),x);assert.equal(Number(attr(m[1],'y')),y);const spans=[...m[2].matchAll(/<tspan ([^>]+)>(.*?)<\/tspan>/g)];assert.deepEqual(spans.map(s=>s[2]),lines);assert.deepEqual(spans.map(s=>Number(attr(s[1],'x'))),lines.map(()=>x));assert.deepEqual(spans.map(s=>Number(attr(s[1],'dy'))),lines.map((_,j)=>j?40:0));});
 const cells=[...svg.matchAll(/<text ([^>]*data-sales-value=[^>]+)>([^<]*)<\/text>/g)];assert.equal(cells.length,6);cells.forEach((m,i)=>{assert.equal(Number(attr(m[1],'data-sales-value')),i);assert.equal(Number(attr(m[1],'x')),[105,235,365,495,625,795][i]);assert.equal(Number(attr(m[1],'y')),345);});const actual=cells.map(m=>m[2]);assert.deepEqual(actual,values[v]);assert.equal(svg.match(/<desc[^>]*>(.*?)<\/desc>/)?.[1],planningReviewedSalesAlt(actual));const texts=[...svg.matchAll(/<text ([^>]+)>/g)];assert.equal(texts.filter(m=>!/\bdata-sales-source-title=/.test(m[1])).length,12);assert.equal(texts.length,13);return{sourceTitle:title[2],cells:actual,headings:headings.map((_,i)=>fixed[i][3].join('')),rules:8,boxes:2,glyphs:[...headings.flatMap((_,i)=>[...fixed[i][3].join('')]),...actual.flatMap(s=>[...s])].length};}
